/**
 * PathFinder用翻訳関数（パラメータ置換対応）
 * v7.3.2: 全プレースホルダー汎用置換対応
 *
 * @param string $key 翻訳キー
 * @param array $params プレースホルダー置換用パラメータ（例: ['locus' => 'opaline', 'n' => 2]）
 * @return string 翻訳済みテキスト
 */
function t_pf(string $key, array $params = []): string {
    global $translations;
    $lang = getLang();

    // 翻訳テキストを取得
    $text = $translations[$lang][$key] ?? $translations['ja'][$key] ?? $key;

    // パラメータ置換 (全てのプレースホルダーを汎用的に置換)
    foreach ($params as $paramKey => $value) {
        // {locus_name} 特殊処理: locus座位の翻訳済み名称
        if ($paramKey === 'locus') {
            // v7.3.17: AgapornisLoci::LOCIから座位名を取得（SSOT）
            $locusKey = strtolower((string)$value);
            $locusName = null;
            if (class_exists('AgapornisLoci') && defined('AgapornisLoci::LOCI') && isset(AgapornisLoci::LOCI[$locusKey])) {
                $locusDef = AgapornisLoci::LOCI[$locusKey];
                $locusName = $locusDef['name'][$lang] ?? $locusDef['name']['ja'] ?? null;
            }
            if (!$locusName) {
                $locusName = $translations[$lang][$value] ?? $translations['ja'][$value] ?? ucfirst($locusKey);
            }
            $text = str_replace('{locus_name}', $locusName, $text);
            // {locus} も翻訳済み名称で置換
            $text = str_replace('{locus}', $locusName, $text);
        }
        // 汎用置換: {paramKey} → value (全てのプレースホルダーに対応)
        $placeholder = '{' . $paramKey . '}';
        if (strpos($text, $placeholder) !== false) {
            $text = str_replace($placeholder, (string)$value, $text);
        }
    }

    return $text;
}

